      "starter": "public class Main {\n    public static double findMedianSortedArrays(int[] a, int[] b) {\n        // TODO: 在较短数组上二分划分点, 使左右两半元素个数相等\n        return 0;\n    }\n}\n",
      "solution": "public class Main {\n    public static double findMedianSortedArrays(int[] a, int[] b) {\n        if (a.length > b.length) { int[] t = a; a = b; b = t; }\n        int m = a.length, n = b.length, half = (m + n + 1) / 2;\n        int lo = 0, hi = m;\n        while (lo <= hi) {\n            int i = (lo + hi) >>> 1, j = half - i;\n            int aL = (i == 0) ? Integer.MIN_VALUE : a[i - 1];\n            int aR = (i == m) ? Integer.MAX_VALUE : a[i];\n            int bL = (j == 0) ? Integer.MIN_VALUE : b[j - 1];\n            int bR = (j == n) ? Integer.MAX_VALUE : b[j];\n            if (aL <= bR && bL <= aR) {\n                int leftMax = Math.max(aL, bL);\n                if (((m + n) & 1) == 1) return leftMax;\n                return (leftMax + (double) Math.min(aR, bR)) / 2.0;\n            } else if (aL > bR) hi = i - 1;\n            else lo = i + 1;\n        }\n        return 0.0;\n    }\n}\n",
