      "starter": "import java.util.*;\n\nclass RandomizedCollection {\n    // TODO: 数组存元素 + Map<值, 下标集合>, 删除时用尾元素回填\n    public RandomizedCollection() { }\n    public boolean insert(int val) { return false; }\n    public boolean remove(int val) { return false; }\n    public int getRandom() { return 0; }\n}\n\npublic class Main { }\n",
      "solution": "import java.util.*;\n\nclass RandomizedCollection {\n    private final List<Integer> nums = new ArrayList<>();\n    private final Map<Integer, Set<Integer>> idx = new HashMap<>();\n    private final Random rnd = new Random();\n\n    public RandomizedCollection() { }\n\n    public boolean insert(int val) {\n        boolean absent = !idx.containsKey(val);\n        idx.computeIfAbsent(val, k -> new HashSet<>()).add(nums.size());\n        nums.add(val);\n        return absent;\n    }\n\n    public boolean remove(int val) {\n        Set<Integer> pos = idx.get(val);\n        if (pos == null || pos.isEmpty()) return false;\n        int i = pos.iterator().next();\n        int last = nums.size() - 1;\n        int tailVal = nums.get(last);\n        nums.set(i, tailVal);\n        pos.remove(i);\n        if (i != last) {\n            Set<Integer> tailPos = idx.get(tailVal);\n            tailPos.remove(last);\n            tailPos.add(i);\n        }\n        nums.remove(last);\n        if (pos.isEmpty()) idx.remove(val);\n        return true;\n    }\n\n    public int getRandom() {\n        return nums.get(rnd.nextInt(nums.size()));\n    }\n}\n\npublic class Main { }\n",
