      "starter": "import java.util.*;\n\nclass TopKTracker {\n    // TODO: 小顶堆只保留最大的 k 个, 同时维护堆内元素之和\n    public TopKTracker(int k) { }\n    public void offer(int score) { }\n    public long topKSum() { return 0L; }\n}\n\npublic class Main { }\n",
      "solution": "import java.util.*;\n\nclass TopKTracker {\n    private final int k;\n    private final PriorityQueue<Integer> heap;\n    private long sum = 0;\n\n    public TopKTracker(int k) {\n        this.k = k;\n        this.heap = new PriorityQueue<>();\n    }\n\n    public void offer(int score) {\n        heap.offer(score);\n        sum += score;\n        while (heap.size() > k) sum -= heap.poll();\n    }\n\n    public long topKSum() {\n        return sum;\n    }\n}\n\npublic class Main { }\n",
